use std :: fmt ; use std :: ops :: Deref ; use schemars :: JsonSchema ; use serde :: { Deserialize , Deserializer , Serialize , Serializer } ; use serde :: de :: Error ; use pretty_assertions :: assert_eq ; use serde_json :: json ; use super :: * ; impl TopK { # [doc = " Creates a new TopK value, returning an error if outside the valid"] # [doc = " range (1 to 1000)"] pub fn new (value : u32) -> Result < Self , String > { if Self :: is_valid (value) { Ok (Self (value)) } else { Err (format ! ("top_k must be between 1 and 1000, got {value}")) } } # [doc = " Creates a new TopK value without validation"] # [doc = ""] # [doc = " # Safety"] # [doc = " This function should only be used when the value is known to be valid"] pub fn new_unchecked (value : u32) -> Self { debug_assert ! (Self :: is_valid (value) , "invalid top_k: {value}") ; Self (value) } # [doc = " Returns true if the top_k value is within the valid range (1 to 1000)"] pub fn is_valid (value : u32) -> bool { (1 ..= 1000) . contains (& value) } # [doc = " Returns the inner u32 value"] pub fn value (& self) -> u32 { self . 0 } }